"""Synthetic, internally related sales/ERP data. No real customer data is read."""

from __future__ import annotations

from datetime import date, datetime, timedelta
from decimal import ROUND_HALF_UP, Decimal
from random import Random
from zoneinfo import ZoneInfo


def today() -> date:
    return datetime.now(ZoneInfo("Europe/Warsaw")).date()


def money(value):
    return float(Decimal(str(value)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))


def price_items(items, products):
    """Controlled arithmetic; never prices generated by a language model."""
    by_id = {p["id"]: p for p in products}
    result = []
    for index, item in enumerate(items):
        product = by_id.get(str(item.get("product_id", "")), {})
        quantity = Decimal(str(item.get("quantity", 1)))
        price = Decimal(str(item.get("price_net", product.get("price_net", 0))))
        discount = Decimal(str(item.get("discount_pct", 0)))
        vat = Decimal(str(item.get("vat", product.get("vat", 23))))
        net = money(quantity * price * (1 - discount / 100))
        vat_total = money(Decimal(str(net)) * vat / 100)
        result.append(
            {
                "id": item.get("id") or f"item-{index + 1}",
                "product_id": product.get("id", item.get("product_id", "")),
                "name": str(
                    item.get("name") or product.get("name") or "Pozycja ręczna"
                ),
                "quantity": float(quantity),
                "unit": item.get("unit") or product.get("unit", "szt."),
                "price_net": float(price),
                "discount_pct": float(discount),
                "vat": float(vat),
                "net": net,
                "vat_total": vat_total,
                "gross": money(Decimal(str(net)) + Decimal(str(vat_total))),
            }
        )
    return result


def totals(items):
    net = money(sum(Decimal(str(i["net"])) for i in items))
    vat = money(sum(Decimal(str(i["vat_total"])) for i in items))
    return {
        "net_total": net,
        "vat_total": vat,
        "gross_total": money(Decimal(str(net)) + Decimal(str(vat))),
    }


