def profile_metadata(state):
    """Add navigation metadata to old sessions without replacing edited records."""
    meta = state["meta"]
    meta.setdefault("profile_id", "legacy")
    meta.setdefault("profile_label", "Własna przestrzeń")
    meta.setdefault(
        "company_short",
        "".join(word[0] for word in meta.get("company", "Demo").split())[:2],
    )
    meta.setdefault(
        "user_name", meta.get("current_user", {}).get("name", "Aleksandra Nowak")
    )
    meta["profile_catalog"] = [dict(item) for item in PROFILE_CATALOG]
    return state


def build_state(reference_date: date | None = None, profile_id: str = "services"):
    state = _build_base_state(reference_date)
    if profile_id == "legacy":
        return profile_metadata(state)
    if profile_id not in PROFILE_DATA:
        raise ValueError("Unknown demo profile")
    profile = PROFILE_DATA[profile_id]
    label = next(item["label"] for item in PROFILE_CATALOG if item["id"] == profile_id)
    state["meta"].update(
        profile_id=profile_id,
        profile_label=label,
        company=profile["company"],
        company_short=profile["short"],
        user_name=state["team"][0]["name"],
    )
    for i, product in enumerate(state["products"]):
        name, category, unit, price, cost, stock = profile["catalog"][i]
        product.update(
            name=name,
            category=category,
            producer=profile["company"],
            variant="Standard",
            unit=unit,
            price_net=price,
            cost_net=cost,
            stock=stock,
            description=f"{name}. Parametry i cena przykładowe.",
        )
    for i, customer in enumerate(state["customers"]):
        customer["contact_role"] = [
            "Kierownik operacyjny",
            "Opiekun zakupów",
            "Koordynator projektu",
            "Właściciel",
        ][i % 4]
        customer["notes"] = (
            "Kontakt demonstracyjny. Ustal potrzeby, zakres, termin i osobę odpowiedzialną za decyzję."
        )
    for i, deal in enumerate(state["deals"]):
        deal.update(
            title=profile["topics"][i % len(profile["topics"])],
            notes="Zakres i termin omówione. Kolejny krok: dopasowana oferta i potwierdzenie warunków.",
        )
    for collection in ("offers", "orders", "invoices"):
        for i, row in enumerate(state[collection]):
            old_gross = Decimal(str(row["gross_total"]))
            fraction = (
                Decimal(str(row.get("paid_gross", 0))) / old_gross
                if old_gross
                else Decimal(0)
            )
            row["items"] = price_items(
                [
                    {
                        key: item[key]
                        for key in ("id", "product_id", "quantity", "discount_pct")
                        if key in item
                    }
                    for item in row["items"]
                ],
                state["products"],
            )
            row.update(totals(row["items"]))
            if "title" in row:
                row["title"] = profile["topics"][i % len(profile["topics"])]
            if collection == "invoices":
                row["paid_gross"] = money(Decimal(str(row["gross_total"])) * fraction)
                row["balance_gross"] = money(row["gross_total"] - row["paid_gross"])
    offers_by_id = {row["id"]: row for row in state["offers"]}
    for order in state["orders"]:
        order["title"] = offers_by_id[order["offer_id"]]["title"]
    for i, license in enumerate(state["licenses"]):
        product = state["products"][i % 4]
        license.update(
            product=f"{profile['contract']}: {product['name']}",
            value_net=money(license["seats"] * product["price_net"]),
        )
    for i, project in enumerate(state["projects"]):
        project["name"] = f"{profile['projects'][i % 3]} — {project['customer']}"
        for j, task in enumerate(project["tasks"]):
            task["title"] = profile["steps"][j]
    for i, task in enumerate(state["tasks"]):
        task["title"] = (
            f"{['Przygotuj ofertę', 'Omów zakres', 'Potwierdź termin', 'Sprawdź realizację'][i % 4]} — {task['customer']}"
        )
        task["description"] = (
            "Potwierdź zakres, odpowiedzialność i kolejny krok z klientem."
        )
    for i, campaign in enumerate(state["campaigns"]):
        campaign.update(
            name=profile["campaigns"][i],
            segment=[
                "Nowi klienci B2B",
                "Firmy i organizacje",
                "Obecni klienci",
                "Wybrana grupa klientów",
            ][i],
        )
    for i, tender in enumerate(state["tenders"]):
        title, scope, requirements = profile["scopes"][i]
        tender.update(
            title=title,
            offer_items=[
                {"product_id": product_id, "quantity": quantity}
                for product_id, quantity in scope
            ],
            requirements=list(requirements),
        )
        products = {product["id"]: product for product in state["products"]}
        tender["needs_summary"] = (
            "; ".join(
                f"{quantity:g} {products[product_id]['unit']} — {products[product_id]['name']}"
                for product_id, quantity in scope
            )
            + ". Termin i miejsce realizacji do potwierdzenia."
        )
        document = next(
            doc for doc in state["documents"] if doc["id"] == tender["document_id"]
        )
        document.update(
            name=f"Zakres: {title} — DEMO.pdf",
            source_text=f"WZÓR ZAKRESU — DOKUMENT DEMONSTRACYJNY\nScenariusz: {title}.\n{tender['needs_summary']}\nWymagania: {'; '.join(requirements)}. Wzór nie wskazuje konkretnego zamawiającego. Ostateczna wycena, dostępność, termin i miejsce wymagają uzgodnienia. Dokument fikcyjny.",
            structured_scope=tender["offer_items"],
            requirements=list(requirements),
            customer="Wzór zakresu",
        )
        tender["source"] = f"Dokument demonstracyjny: {document['name']}"
    names = [
        "Specyfikacja",
        "Referencje zespołu",
        "Zakres realizacji",
        "Katalog produktów i usług",
        "Wymagania techniczne",
        "Instrukcja pracy z klientem",
        "Protokół odbioru",
        "Warunki współpracy cyklicznej",
    ]
    for i, document in enumerate(state["documents"]):
        if not document.get("structured_scope"):
            document.update(
                name=f"{names[i]} — DEMO.pdf",
                source_text=f"MATERIAŁ DEMONSTRACYJNY — {names[i].upper()}\n{profile['company']}: {'; '.join(profile['steps'])}. Zakres obejmuje przykładowe działania dla profilu {label.lower()}. Sprawdź zakres, ilości, termin, warunki płatności i odpowiedzialność. Materiał fikcyjny.",
            )
    for i, mail in enumerate(state["messages"]):
        customer = next(c for c in state["customers"] if c["id"] == mail["customer_id"])
        title, scope, _ = profile["scopes"][i % 4]
        scope_text = "; ".join(
            f"{quantity:g} {products[product_id]['unit']} {products[product_id]['name']}"
            for product_id, quantity in scope
        )
        mail["subject"] = [
            f"Prośba o ofertę: {title}",
            "Ustalenie terminu rozmowy",
            f"Zakres do wyceny: {title}",
            "Potwierdzenie warunków współpracy",
        ][i % 4]
        mail["body"] = (
            f"Dzień dobry,\n\nproszę o propozycję dla firmy {customer['name']}. Interesuje nas: {scope_text}. Proszę wskazać zakres, dostępność i możliwy termin.\n\nPozdrawiam\n{customer['contact_name']}\n\nWiadomość demonstracyjna."
            if mail["direction"] == "inbound"
            else f"Dzień dobry,\n\ndziękuję za rozmowę. Przekazujemy podsumowanie zakresu: {scope_text}. Po potwierdzeniu ilości i terminu przygotujemy propozycję.\n\nPozdrawiam\n{state['meta']['user_name']}\n{profile['company']}\n\nWiadomość demonstracyjna."
        )
        for attachment in mail["attachments"]:
            document_id = state["tenders"][i % 4]["document_id"]
            document = next(
                doc for doc in state["documents"] if doc["id"] == document_id
            )
            attachment.update(name=document["name"], url=document["pdf_url"])
    state["automations"][1].update(
        name="Odnowienie współpracy 30 dni wcześniej",
        trigger="30 dni do końca umowy",
        action="Zadanie i szansa odnowienia",
    )
    return profile_metadata(state)


def enrich(state):
    """Compute dashboard values from the same records used by the ERP lists."""
    profile_metadata(state)
    day = date.fromisoformat(state["meta"]["date"])
    invoices = state["invoices"]
    for invoice in invoices:
        invoice["balance_gross"] = money(
            max(0, invoice["gross_total"] - invoice["paid_gross"])
        )
        if not invoice["balance_gross"]:
            invoice["status"] = "paid"
        elif invoice["due_date"] < day.isoformat():
            invoice["status"] = "overdue"
        elif invoice["paid_gross"] > 0:
            invoice["status"] = "partial"
        else:
            invoice["status"] = "unpaid"
    revenue = money(sum(i["net_total"] for i in invoices))
    cost = money(revenue * 0.617)
    open_deals = [d for d in state["deals"] if d["stage"] not in {"won", "lost"}]
    stats = {
        "revenue_net": revenue,
        "cost_net": cost,
        "profit_net": money(revenue - cost),
        "margin": money((revenue - cost) / revenue * 100) if revenue else 0,
        "receivables_net": money(
            sum(
                i["balance_gross"] / i["gross_total"] * i["net_total"]
                for i in invoices
                if i["gross_total"]
            )
        ),
        "receivables_gross": money(sum(i["balance_gross"] for i in invoices)),
        "overdue_net": money(
            sum(
                i["balance_gross"] / i["gross_total"] * i["net_total"]
                for i in invoices
                if i["status"] == "overdue" and i["gross_total"]
            )
        ),
        "overdue_gross": money(
            sum(i["balance_gross"] for i in invoices if i["status"] == "overdue")
        ),
        "pipeline_net": money(sum(d["value_net"] for d in open_deals)),
        "weighted_pipeline_net": money(
            sum(d["value_net"] * d["probability"] / 100 for d in open_deals)
        ),
        "won_net": money(
            sum(d["value_net"] for d in state["deals"] if d["stage"] == "won")
        ),
        "customers": len(state["customers"]),
        "open_deals": len(open_deals),
        "tasks_due": sum(
            t["status"] != "done" and t["date"] <= day.isoformat()
            for t in state["tasks"]
        ),
        "unread_messages": sum(
            not m["read"] and m["direction"] == "inbound" for m in state["messages"]
        ),
        "expiring_licenses": sum(l["status"] == "expiring" for l in state["licenses"]),
        "offers_net": money(sum(o["net_total"] for o in state["offers"])),
        "campaign_sent": sum(c["sent"] for c in state["campaigns"]),
        "campaign_replies": sum(c["replies"] for c in state["campaigns"]),
        "campaign_positive": sum(c["positive"] for c in state["campaigns"]),
        "active_projects": sum(p["status"] == "active" for p in state["projects"]),
        "revenue_growth": 0,
        "conversion": money(
            sum(d["stage"] == "won" for d in state["deals"])
            / max(1, sum(d["stage"] in {"won", "lost"} for d in state["deals"]))
            * 100
        ),
    }
    state["stats"] = stats
    series = []
    for month in range(1, day.month + 1):
        value = money(
            sum(
                i["net_total"]
                for i in invoices
                if i["date"].startswith(f"{day.year}-{month:02d}")
            )
        )
        mc = money(value * 0.617)
        series.append(
            {
                "month": [
                    "Sty",
                    "Lut",
                    "Mar",
                    "Kwi",
                    "Maj",
                    "Cze",
                    "Lip",
                    "Sie",
                    "Wrz",
                    "Paź",
                    "Lis",
                    "Gru",
                ][month - 1],
                "month_key": f"{day.year}-{month:02d}",
                "revenue": value,
                "cost": mc,
                "profit": money(value - mc),
                "goal": 240000,
            }
        )
    state["revenue_series"] = series
    state["meta"]["financial_model"] = (
        "Przychód pochodzi z fikcyjnych faktur, koszty to demonstracyjny model 61,7% przychodu. Nie jest to księga rachunkowa. Wzrost porównuje dwa ostatnie pełne miesiące."
    )
    if len(series) > 2:
        previous, latest = series[-3], series[-2]
        stats["revenue_growth"] = (
            money((latest["revenue"] - previous["revenue"]) / previous["revenue"] * 100)
            if previous["revenue"]
            else 0
        )
    for customer in state["customers"]:
        customer["revenue_net"] = money(
            sum(i["net_total"] for i in invoices if i["customer_id"] == customer["id"])
        )
        customer["value_net"] = money(
            sum(
                d["value_net"] for d in open_deals if d["customer_id"] == customer["id"]
            )
        )
    for member in state["team"]:
        member["open_deals"] = sum(d["owner_id"] == member["id"] for d in open_deals)
        member["revenue_net"] = money(
            sum(i["net_total"] for i in invoices if i.get("owner") == member["name"])
        )
    return state
